import os, sys

root = "unpacked"
for dirpath, dirnames, filenames in os.walk(root):
    for f in filenames:
        full = os.path.join(dirpath, f)
        print(f"{full} ({os.path.getsize(full)} bytes)")

from defusedxml import minidom

dom = minidom.parse("unpacked/word/document.xml")
body = dom.getElementsByTagName("w:body")[0]

def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)

for i, p in enumerate(body.getElementsByTagName("w:p")):
    txt = para_text(p)
    print(f"[{i}] {txt!r}")

